sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) return;

    var openedBy = g_form.getValue('opened_by'); 
    if (!openedBy) return;

    g_form.getReference('course', function(course) {
        if (!course) return;

        var instructor = course.instructor || course.u_instructor;

        if (instructor === openedBy) {
            g_form.clearValue('course');
            g_form.showFieldMsg('course', 'You cannot enroll a user who is the instructor of this course.', 'error');
        } else {
            g_form.hideFieldMsg('course');
        }
    });
}
